package com.cloudmall.pay;
import com.cloudmall.common.api.ApiResponse;import com.cloudmall.common.auth.AuthContext;import com.cloudmall.common.error.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.time.*;import java.util.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;
@RestController @RequestMapping("/api/payments") public class PayController{
 private final OrderClient orders;private final JdbcTemplate db;@Value("${cloudmall.internal.callback-token:cloudmall-local-callback}") private String callbackToken;public PayController(OrderClient orders,JdbcTemplate db){this.orders=orders;this.db=db;}
 @Transactional @PostMapping public synchronized ApiResponse<?> create(@RequestHeader("Idempotency-Key")String key,@RequestBody Request req){long uid=AuthContext.requireUserId();if(key==null||key.isBlank()||req==null||req.orderNo==null||req.payAmount==null||req.payAmount.signum()<0)throw new BizException(ErrorCodes.INVALID,"支付参数不完整",400);OrderClient.OrderView o=order(req.orderNo,uid);if(!Objects.equals(uid,o.userId()))throw new BizException(ErrorCodes.FORBIDDEN,"无权支付此订单",403);if(!"PENDING_PAYMENT".equals(o.status()))throw new BizException(ErrorCodes.PAY_DONE,"订单不处于待支付状态",409);if(req.payAmount.compareTo(o.payAmount())!=0)throw new BizException(ErrorCodes.PAY_MISMATCH,"支付金额与订单应付金额不一致",409);String no=payNoFor(uid,key);List<Pay> keyed=db.query("select pay_no,order_no,user_id,amount,status,paid_at from pay_record where pay_no=?",(r,n)->pay(r),no);if(!keyed.isEmpty()){Pay p=keyed.get(0);if(!Objects.equals(p.orderNo,req.orderNo)||!Objects.equals(p.userId,uid)||p.amount.compareTo(req.payAmount)!=0)throw new BizException(ErrorCodes.DUPLICATE,"Idempotency-Key已用于其他支付请求",409);return ApiResponse.ok(p);}List<Pay> old=db.query("select pay_no,order_no,user_id,amount,status,paid_at from pay_record where order_no=?",(r,n)->pay(r),req.orderNo);if(!old.isEmpty())return ApiResponse.ok(old.get(0));db.update("insert into pay_record(id,pay_no,order_no,user_id,amount,status,created_at,updated_at) values(?,?,?,?,?,'PENDING',?,?)",id(),no,req.orderNo,uid,req.payAmount,ts(now()),ts(now()));return ApiResponse.ok(find(no));}
 @GetMapping("/orders/{orderNo}")public ApiResponse<?> get(@PathVariable String orderNo){long uid=AuthContext.requireUserId();List<Pay>x=db.query("select pay_no,order_no,user_id,amount,status,paid_at from pay_record where order_no=? and user_id=?",(r,n)->pay(r),orderNo,uid);if(x.isEmpty())throw new BizException(ErrorCodes.NOT_FOUND,"支付记录不存在",404);return ApiResponse.ok(x.get(0));}
 @Transactional @PostMapping("/{payNo}/mock-success")public ApiResponse<?> success(@PathVariable("payNo") String payNo){Pay p=owned(payNo);if("SUCCESS".equals(p.status))return ApiResponse.ok(p);if(!"PENDING".equals(p.status))throw new BizException(ErrorCodes.PAY_DONE,"支付已处理",409);if(db.update("update pay_record set status='SUCCESS',paid_at=?,updated_at=? where pay_no=? and status='PENDING'",ts(now()),ts(now()),payNo)!=1)throw new BizException(ErrorCodes.PAY_DONE,"支付状态已被处理",409);orders.paid(p.orderNo,p.userId);return ApiResponse.ok(find(payNo));}
 @Transactional @PostMapping("/{payNo}/mock-fail")public ApiResponse<?> fail(@PathVariable("payNo") String payNo){Pay p=owned(payNo);if("SUCCESS".equals(p.status))throw new BizException(ErrorCodes.PAY_DONE,"支付已成功",409);notifyFailure(p);if(db.update("update pay_record set status='FAILED',updated_at=? where pay_no=? and status='PENDING'",ts(now()),payNo)!=1)throw new BizException(ErrorCodes.PAY_DONE,"支付状态已被处理",409);return ApiResponse.ok(find(payNo));}
 @Transactional @PostMapping("/callback")public ApiResponse<?> callback(@RequestHeader(value="X-Internal-Callback-Token",required=false)String token,@RequestBody Callback c){if(!Objects.equals(callbackToken,token))throw new BizException(ErrorCodes.FORBIDDEN,"回调凭证无效",403);if(c==null||c.payNo==null||c.payNo.isBlank()||c.amount==null||c.userId==null)throw new BizException(ErrorCodes.INVALID,"回调参数不完整",400);String cb=c.callbackId==null||c.callbackId.isBlank()?c.payNo:c.callbackId;if(!db.query("select pay_no from pay_callback_log where callback_id=?",(r,n)->r.getString(1),cb).isEmpty())return ApiResponse.ok(find(c.payNo));Pay p=find(c.payNo);if(!Objects.equals(p.userId,c.userId)||p.amount.compareTo(c.amount)!=0)throw new BizException(ErrorCodes.PAY_MISMATCH,"回调订单归属或金额不一致",409);if("PENDING".equals(p.status)){db.update("update pay_record set status=?,paid_at=case when ? then ? else paid_at end,updated_at=? where pay_no=? and status='PENDING'",c.success?"SUCCESS":"FAILED",c.success,ts(now()),ts(now()),p.payNo);if(c.success)orders.paid(p.orderNo,p.userId);else notifyFailure(p);}else if("SUCCESS".equals(p.status)&&!c.success)throw new BizException(ErrorCodes.PAY_DONE,"支付已成功",409);db.update("insert into pay_callback_log(id,pay_no,callback_id,callback_status,payload,processed_at,created_at) values(?,?,?,?,?,?,?)",id(),p.payNo,cb,c.success?"SUCCESS":"FAILED","{}",ts(now()),ts(now()));return ApiResponse.ok(find(p.payNo));}
 private void notifyFailure(Pay p){try{ApiResponse<?> response=orders.cancel(p.orderNo,p.userId);if(response==null||!"0".equals(response.code))throw new BizException(ErrorCodes.INTERNAL,"订单失败回滚未确认",500);}catch(BizException e){throw e;}catch(Exception e){throw new BizException(ErrorCodes.INTERNAL,"订单失败回滚失败",500);}}private OrderClient.OrderView order(String no,long uid){ApiResponse<OrderClient.OrderView>r=orders.get(no,uid);if(r==null||r.data==null)throw new BizException(ErrorCodes.NOT_FOUND,"订单不存在",404);return r.data;}private Pay owned(String no){Pay p=find(no);if(!Objects.equals(p.userId,AuthContext.requireUserId()))throw new BizException(ErrorCodes.FORBIDDEN,"无权访问此支付记录",403);return p;}private Pay find(String no){List<Pay>x=db.query("select pay_no,order_no,user_id,amount,status,paid_at from pay_record where pay_no=?",(r,n)->pay(r),no);if(x.isEmpty())throw new BizException(ErrorCodes.NOT_FOUND,"支付记录不存在",404);return x.get(0);}private static String payNoFor(long uid,String key){try{byte[] hash=MessageDigest.getInstance("SHA-256").digest((uid+":"+key).getBytes(StandardCharsets.UTF_8));StringBuilder b=new StringBuilder();for(byte x:hash)b.append(String.format("%02x",x));return b.substring(0,48);}catch(Exception e){throw new IllegalStateException(e);}}private static Pay pay(java.sql.ResultSet r)throws java.sql.SQLException{Pay p=new Pay();p.payNo=r.getString(1);p.orderNo=r.getString(2);p.userId=r.getLong(3);p.amount=r.getBigDecimal(4);p.status=r.getString(5);if(r.getTimestamp(6)!=null)p.paidAt=r.getTimestamp(6).toInstant().atOffset(ZoneOffset.ofHours(8)).toString();return p;}private static OffsetDateTime now(){return OffsetDateTime.now(ZoneOffset.ofHours(8));}private static java.sql.Timestamp ts(OffsetDateTime x){return java.sql.Timestamp.from(x.toInstant());}private static long id(){return Math.abs(UUID.randomUUID().getMostSignificantBits());}
 public static class Request{public String orderNo;public BigDecimal payAmount;}public static class Callback{public String payNo;public boolean success;public String callbackId;public BigDecimal amount;public Long userId;}public static class Pay{public String payNo,orderNo,status,paidAt;public Long userId;public BigDecimal amount;}
}
